class Recorder:
    def __init__(self):
        self.emitted = []

    def record(self, event):
        self.emitted.append(event)

_cache = {}

def handle(key):
    if key in _cache:
        return _cache[key]
    _cache[key] = compute(key)
    return _cache[key]

def step(counter, max_tries):
    if counter >= max_tries:
        return "stop"
    return "retry"

def classify(n):
    if n < 0:
        return "neg"
    if n == 0:
        return "zero"
    return "pos"

class Router:
    def __init__(self, name):
        self._name = name

    def route(self, arg):
        return getattr(self, self._name)(arg)

class Middleware:
    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        return await self.app(scope, receive, send)

class Guard:
    def __init__(self, check):
        self._check = check

    def allow(self, req):
        if self._check(req):
            return "ok"
        return "deny"

class Router:
    def __init__(self, handler):
        self._h = handler

    def swap(self, handler):
        self._h = handler

    def route(self, req):
        return self._h(req)

class Host:
    def __init__(self, sink):
        self._sink = sink

    def configure(self):
        self._sink.limit = 10

    def run(self, req):
        return self._sink(req)

typedef int (*Handler)(int);
static Handler handler;

int route(int r) { return handler(r); }

mode = {}

def run(x):
    if mode.get(x):
        return do_a(x)
    return do_b(x)

import importlib

def send(dotted_target, payload):
    fn = importlib.import_module(dotted_target).handle
    return fn(payload)

HANDLERS = {"a": handle_a, "b": handle_b}

def dispatch(kind, arg):
    return HANDLERS[kind](arg)

TABLE = {("idle", "go"): "run", ("run", "stop"): "idle"}

def next_state(state, event):
    return TABLE.get((state, event), state)
